/*
 * A136110  Limiting sequence when we start with the positive integers
 *          (A000027) and delete in step n >= 1 the term at position n +
 *          tau(a(n)), where tau(k) is the number of divisors of k.
 * https://oeis.org/A136110
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 67, u16 n <= 67, u32 n <= 67, u64 n <= 67, u128 n <= 67,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A136110 – Limiting sequence generated by successive deletions.
   Formula: a(n) is the n-th element of a list that starts as the
   positive integers. In step n (n ≥ 1) the element a(n) is taken from
   the current list, and the element at position n+τ(a(n)) (τ = number
   of divisors) is removed.  a(n) is the element selected in step n.
*/

#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <assert.h>

/* Choose a bound that is comfortably larger than all a(n) for n≤10000.
   In experiments the values stay below ~20000, so 2 000 000 is ample. */
#define MAXL 2000000   /* sizes are 1‑based up to this index */

/* Fenwick tree for order statistics of the set {1,…,MAXL} with deletions. */
static int *BIT = NULL;       /* 1‑based Fenwick tree, size MAXL+1 */
static int *divcnt = NULL;    /* τ(k) for 1 ≤ k ≤ MAXL */
static seq_t *seq  = NULL;    /* memoised a(n); seq[0] unused. */
static size_t seq_cap = 0;    /* capacity of seq array (≥ curMax). */
static idx_t curMax = 0;      /* largest n already computed. */
static size_t remaining = 0;  /* how many elements still present in BIT. */

/* ---- Fenwick tree helpers ------------------------------------------------ */
static void bit_add(size_t idx, int delta)
{
    for (size_t i = idx; i <= (size_t)MAXL; i += i & -i)
        BIT[(int)i] += delta;
}

static size_t bit_find_kth(size_t k)
{
    /* Finds the smallest index idx with prefix sum >= k. */
    size_t idx = 0;
    size_t bitMask = 1;
    while (bitMask <= (size_t)MAXL) bitMask <<= 1;
    bitMask >>= 1;
    while (bitMask) {
        size_t next = idx + bitMask;
        if (next <= (size_t)MAXL && (size_t)BIT[(int)next] < k) {
            idx = next;
            k -= (size_t)BIT[(int)next];
        }
        bitMask >>= 1;
    }
    return idx + 1;   /* 1‑based position of the k-th remaining element */
}

/* ---- Lazy initialisation ------------------------------------------------ */
static void initialise(void)
{
    /* Allocate BIT with all positions present initially (value = 1). */
    BIT = (int *)malloc((MAXL + 1) * sizeof(int));
    if (!BIT) abort();
    for (size_t i = 1; i <= (size_t)MAXL; ++i) {
        BIT[(int)i] = (int)(i & -i);
    }

    /* Precompute τ(k) for 1 … MAXL. */
    divcnt = (int *)calloc((MAXL + 1), sizeof(int));
    if (!divcnt) abort();
    for (size_t i = 1; i <= (size_t)MAXL; ++i) {
        for (size_t j = i; j <= (size_t)MAXL; j += i) {
            ++divcnt[(int)j];
        }
    }

    /* Allocate sequenced array. */
    seq_cap = 256;
    seq = (seq_t *)malloc((seq_cap + 1) * sizeof(seq_t));
    if (!seq) abort();
    seq[0] = 0;

    remaining = MAXL;  /* all elements present at start */
}

/* ---- Public function ----------------------------------------------------- */
seq_t a(idx_t n)
{
    if (!BIT) initialise();   /* lazy initialisation */

    if (n == 0) return 0;     /* offset is 1 */

    /* Already computed? */
    if (curMax >= n)
        return seq[(size_t)n];

    /* Compute terms up to n. */
    for (idx_t i = curMax + 1; i <= n; ++i) {
        /* a(i) is the i‑th element of current list. */
        assert(((size_t)i) <= remaining);
        size_t value = bit_find_kth((size_t)i);
        seq[(size_t)i] = (seq_t)value;

        /* Delete element at position i + τ(a(i)) in the current list. */
        size_t tau = (size_t)divcnt[(int)value];
        size_t delpos = (size_t)i + tau;
        /* Guard against out‑of‑range: the definition guarantees delpos ≤ remaining. */
        assert(delpos <= remaining);
        size_t delvalue = bit_find_kth(delpos);
        bit_add(delvalue, -1);
        --remaining;
    }

    curMax = n;

    /* Ensure sequence array capacity. */
    if ((size_t)n > seq_cap) {
        size_t new_cap = seq_cap;
        while ((size_t)n > new_cap) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(seq, (new_cap + 1) * sizeof(seq_t));
        if (!tmp) abort();
        seq = tmp;
        seq_cap = new_cap;
    }

    return seq[(size_t)n];
}
